import java.util.Scanner;

public class Main {
    static final long N = 1000000007;

    static long powerMod(long base, long exp, long mod) {
        long result = 1;
        for (long i = 0; i < exp; i++) {
            result = (result * base) % mod;
        }
        return result;
    }

    static long fastModPow(long base, long exp) {
        long result = 1;
        for (long i = 0; i < exp; i++) {
            result = (result * base) % N;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k % p == 1) {
            System.out.println(fastModPow(p, p));
            return;
        }
        if (k % p == 0) {
            System.out.println(fastModPow(p, p - 1));
            return;
        }

        long a = 1;
        while (true) {
            if ((p - 1) % a != 0) {
                a++;
                continue;
            }
            if (powerMod(k, a, p) == 1) {
                break;
            } else {
                a++;
            }
        }
        System.out.println(fastModPow(p, (p - 1) / a));
    }
}
